#include <cmath>
#include <optional>

struct Vec3 {
    double x, y, z;

    Vec3 operator-(const Vec3& b) const {
        return {x - b.x, y - b.y, z - b.z};
    }

    Vec3 operator+(const Vec3& b) const {
        return {x + b.x, y + b.y, z + b.z};
    }

    Vec3 operator*(double s) const {
        return {x * s, y * s, z * s};
    }
};

double dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

Vec3 cross(const Vec3& a, const Vec3& b) {
    return {
        a.y*b.z - a.z*b.y,
        a.z*b.x - a.x*b.z,
        a.x*b.y - a.y*b.x
    };
}

struct Ray {
    Vec3 origin;
    Vec3 direction;
};

struct Triangle {
    Vec3 a, b, c;
};

struct Hit {
    double t;
    double u;
    double v;
    Vec3 position;
    Vec3 normal;
};

std::optional<Hit> intersectTriangle(
    const Ray& ray,
    const Triangle& tri,
    double tMin,
    double tMax)
{
    const Vec3 e1 = tri.b - tri.a;
    const Vec3 e2 = tri.c - tri.a;

    // Unnormalized triangle normal.
    const Vec3 n = cross(e1, e2);
    const double n2 = dot(n, n);

    // Reject zero-area triangles in this reference algorithm.
    if (n2 == 0.0)
        return std::nullopt;

    const Vec3 p = cross(ray.direction, e2);
    const double det = dot(e1, p);

    // This exact comparison is only the reference arithmetic
    // decision, not a robust production predicate.
    if (det == 0.0)
        return std::nullopt;

    const double invDet = 1.0 / det;
    const Vec3 s = ray.origin - tri.a;

    const double u = dot(s, p) * invDet;
    if (u < 0.0 || u > 1.0)
        return std::nullopt;

    const Vec3 q = cross(s, e1);

    const double v = dot(ray.direction, q) * invDet;
    if (v < 0.0 || u + v > 1.0)
        return std::nullopt;

    const double t = dot(e2, q) * invDet;
    if (t < tMin || t > tMax)
        return std::nullopt;

    const double invNormalLength = 1.0 / std::sqrt(n2);
    Vec3 normal = n * invNormalLength;

    // Return a face-forward normal as this API's convention.
    // A geometric outward normal would preserve original winding.
    if (dot(normal, ray.direction) > 0.0)
        normal = normal * -1.0;

    return Hit{
        t, u, v,
        ray.origin + ray.direction * t,
        normal
    };
}

