#include <stdexcept>

struct AABBSoA {
    std::vector<float> minX, minY, minZ;
    std::vector<float> maxX, maxY, maxZ;

    std::size_t size() const noexcept {
        return minX.size();
    }

    void add(
        float x0, float y0, float z0,
        float x1, float y1, float z1)
    {
        if (x0 > x1 || y0 > y1 || z0 > z1)
            throw std::invalid_argument("Invalid AABB");

        // In production, reserve capacity for all six
        // arrays before batch insertion. Otherwise a
        // throwing allocation can leave sizes inconsistent.
        minX.push_back(x0);
        minY.push_back(y0);
        minZ.push_back(z0);

        maxX.push_back(x1);
        maxY.push_back(y1);
        maxZ.push_back(z1);
    }

    bool validLayout() const noexcept {
        const std::size_t n = minX.size();

        return minY.size() == n &&
               minZ.size() == n &&
               maxX.size() == n &&
               maxY.size() == n &&
               maxZ.size() == n;
    }
};

#include <cstdint>
