enum class DebugEventType : std::uint8_t {
    CandidateBox,
    TestedTriangle,
    SeparatingAxis,
    RejectedAxis,
    AcceptedHit,
    ContactPoint
};

struct CollisionDebugEvent {
    DebugEventType type{};

    std::uint32_t primitiveID = 0;

    Vec3 position{};
    Vec3 direction{};

    double scalar = 0.0;
};

struct CollisionDebugTrace {
    std::vector<CollisionDebugEvent> events;

    void record(
        DebugEventType type,
        std::uint32_t primitive,
        Vec3 position,
        Vec3 direction,
        double value)
    {
        events.push_back({
            type,
            primitive,
            position,
            direction,
            value
        });
    }
};
